import { describe, expect, it } from 'vitest';
import { resolveIsolation, scopeCss } from './Solution';

/**
 * 断言由 fe_gen.py 里同一份 Python 模型（_resolve_sandbox / _rule_style）生成，不手抄 ——
 * react-vitest 题的判分事实来源就是这份测试文件，抄错一次就永久错一次。
 * 契约型用例断言到**消息**：只写 .toThrow() 会让几条"都该抛错"的用例收敛成同一条。
 */
describe('resolveIsolation：微前端隔离档位的三种出口', () => {
  it("基线：全支持 + sandbox:true ⇒ 严格 Proxy 沙箱，一条告警都不该有", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": true, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": [], "thrown": []});
  });
  it("降级：无 Proxy 且显式 singular:false ⇒ 快照沙箱 + 两条告警，但 singular 不许被改", () => {
    expect(resolveIsolation({"hasProxy": false, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": true, "singular": false, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Snapshot", "singular": false, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": ["[qiankun] Missing window.Proxy, proxySandbox will degenerate into snapshotSandbox", "[qiankun] Setting singular as false may cause unexpected behavior while your browser not support window.Proxy"], "thrown": []});
  });
  it("降级：loose 显式开 ⇒ LegacyProxy（严格模式才是默认）", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": {"loose": true}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "LegacyProxy", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": [], "thrown": []});
  });
  it("降级不吞配置：无 Proxy 时 experimentalStyleIsolation 要活下来（展开后补 loose）", () => {
    expect(resolveIsolation({"hasProxy": false, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": {"experimentalStyleIsolation": true}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Snapshot", "singular": true, "scopedCss": true, "shadowWrapped": false, "containerAttr": "react16", "warnings": ["[qiankun] Missing window.Proxy, proxySandbox will degenerate into snapshotSandbox"], "thrown": []});
  });
  it("硬失败：legacy render + 两档隔离同开 ⇒ 只有 strict 那条抛错，且两档互斥（scopedCss 为假）", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": true, "sandbox": {"strictStyleIsolation": true, "experimentalStyleIsolation": true}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": false, "shadowWrapped": true, "containerAttr": null, "warnings": [], "thrown": ["strictStyleIsolation can not be used with legacy render!"]});
  });
  it("硬失败：legacy render + experimental ⇒ 抛对应那条，但容器标识已经写上了", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": true, "sandbox": {"experimentalStyleIsolation": true}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": true, "shadowWrapped": false, "containerAttr": "react16", "warnings": [], "thrown": ["experimentalStyleIsolation can not be used with legacy render!"]});
  });
  it("静默降级：不支持 shadow dom 时开 strict ⇒ 只 warn 并忽略，绝不进 thrown", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": false, "legacyRender": false, "sandbox": {"strictStyleIsolation": true}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": ["[qiankun]: As current browser not support shadow dom, your strictStyleIsolation configuration will be ignored!"], "thrown": []});
  });
  it("三种出口同现：无 Proxy + singular:false + 无 shadow dom + legacy render + strict", () => {
    expect(resolveIsolation({"hasProxy": false, "hasConstDestructAssignment": true, "supportsShadowDOM": false, "legacyRender": true, "sandbox": {"strictStyleIsolation": true}, "singular": false, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Snapshot", "singular": false, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": ["[qiankun] Missing window.Proxy, proxySandbox will degenerate into snapshotSandbox", "[qiankun] Setting singular as false may cause unexpected behavior while your browser not support window.Proxy", "[qiankun]: As current browser not support shadow dom, your strictStyleIsolation configuration will be ignored!"], "thrown": ["strictStyleIsolation can not be used with legacy render!"]});
  });
  it("speedy：不支持 const 解构且没显式关 ⇒ 只追加一条\"关掉 speedy\"的告警", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": false, "supportsShadowDOM": true, "legacyRender": false, "sandbox": true, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": ["[qiankun] Speedy mode will turn off as const destruct assignment not supported in current browser!"], "thrown": []});
  });
  it("speedy 已显式关闭 ⇒ 不该再报\"我要关掉它\"", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": false, "supportsShadowDOM": true, "legacyRender": false, "sandbox": {"speedy": false}, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": [], "thrown": []});
  });
  it("分支互斥：无 Proxy 时先返回，const 解构不支持也不该再报 speedy", () => {
    expect(resolveIsolation({"hasProxy": false, "hasConstDestructAssignment": false, "supportsShadowDOM": true, "legacyRender": false, "sandbox": true, "singular": true, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "Snapshot", "singular": true, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": ["[qiankun] Missing window.Proxy, proxySandbox will degenerate into snapshotSandbox"], "thrown": []});
  });
  it("退化：sandbox:false ⇒ 不降级、不告警，singular:false 原样保留（沙箱压根没建）", () => {
    expect(resolveIsolation({"hasProxy": false, "hasConstDestructAssignment": false, "supportsShadowDOM": false, "legacyRender": false, "sandbox": false, "singular": false, "appName": "react16", "instanceSeq": 1})).toEqual({"sandboxType": "None", "singular": false, "scopedCss": false, "shadowWrapped": false, "containerAttr": null, "warnings": [], "thrown": []});
  });
  it("实例标识：同名第 3 次加载 ⇒ 容器属性值是 react16_2，不是 react16", () => {
    expect(resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": {"experimentalStyleIsolation": true}, "appName": "react16", "instanceSeq": 3})).toEqual({"sandboxType": "Proxy", "singular": true, "scopedCss": true, "shadowWrapped": false, "containerAttr": "react16_2", "warnings": [], "thrown": []});
  });
  it("非法：整行是 null", () => {
    expect(() => resolveIsolation(null as never)).toThrow("input must be an object");
  });
  it("非法：sandbox 写成字符串（true/false/对象之外的第四种）", () => {
    expect(() => resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": "yes", "singular": true, "appName": "react16", "instanceSeq": 1} as never)).toThrow("unknown sandbox configuration");
  });
  it("非法：instanceSeq 为 0（加载序从 1 开始）", () => {
    expect(() => resolveIsolation({"hasProxy": true, "hasConstDestructAssignment": true, "supportsShadowDOM": true, "legacyRender": false, "sandbox": {"experimentalStyleIsolation": true}, "appName": "react16", "instanceSeq": 0} as never)).toThrow("instanceSeq must be a positive integer");
  });
});

describe('scopeCss：运行时 scoped CSS 的改写规则', () => {
  it("基线：普通规则加前缀，@font-face 与 @keyframes 一个字都不动", () => {
    const rules = [{"type": 1, "text": ".app-main", "declarations": "{font-size: 14px}"}, {"type": 5, "text": "@font-face{font-family:icon;src:url(icon.woff)}"}, {"type": 7, "text": "@keyframes fadeIn{from{opacity:0}to{opacity:1}}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("div[data-qiankun=\"react16\"] .app-main {font-size: 14px}@font-face{font-family:icon;src:url(icon.woff)}@keyframes fadeIn{from{opacity:0}to{opacity:1}}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 1, "text": ".app-main", "declarations": "{font-size: 14px}"}, {"type": 5, "text": "@font-face{font-family:icon;src:url(icon.woff)}"}, {"type": 7, "text": "@keyframes fadeIn{from{opacity:0}to{opacity:1}}"}]);
  });
  it("根选择器：html / body / :root 是被**替换**成容器，不是加前缀", () => {
    const rules = [{"type": 1, "text": "html", "declarations": "{margin: 0}"}, {"type": 1, "text": "body", "declarations": "{padding: 0}"}, {"type": 1, "text": ":root", "declarations": "{--brand: blue}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("div[data-qiankun=\"react16\"] {margin: 0}div[data-qiankun=\"react16\"] {padding: 0}div[data-qiankun=\"react16\"] {--brand: blue}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 1, "text": "html", "declarations": "{margin: 0}"}, {"type": 1, "text": "body", "declarations": "{padding: 0}"}, {"type": 1, "text": ":root", "declarations": "{--brand: blue}"}]);
  });
  it("组合选择器：html body 与 html > body 先剥掉 html 前缀", () => {
    const rules = [{"type": 1, "text": "html body", "declarations": "{color: red}"}, {"type": 1, "text": "html > body", "declarations": "{color: green}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("div[data-qiankun=\"react16\"] {color: red}div[data-qiankun=\"react16\"] {color: green}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 1, "text": "html body", "declarations": "{color: red}"}, {"type": 1, "text": "html > body", "declarations": "{color: green}"}]);
  });
  it("非标准兄弟规则：不剥前缀，但两个根选择器照样各自被替换（素材说\"原样\"是错的）", () => {
    const rules = [{"type": 1, "text": "html + body", "declarations": "{color: red}"}, {"type": 1, "text": "html ~ body", "declarations": "{color: blue}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("div[data-qiankun=\"react16\"] +div[data-qiankun=\"react16\"] {color: red}div[data-qiankun=\"react16\"] ~div[data-qiankun=\"react16\"] {color: blue}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 1, "text": "html + body", "declarations": "{color: red}"}, {"type": 1, "text": "html ~ body", "declarations": "{color: blue}"}]);
  });
  it("组选择器：逐段处理，段首的逗号/括号不能被吃掉（body,html 与 *:not(:root)）", () => {
    const rules = [{"type": 1, "text": "div, body, span", "declarations": "{color: red}"}, {"type": 1, "text": "body,html", "declarations": "{margin: 0}"}, {"type": 1, "text": "*:not(:root)", "declarations": "{color: red}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("div[data-qiankun=\"react16\"] div,div[data-qiankun=\"react16\"],div[data-qiankun=\"react16\"] span {color: red}div[data-qiankun=\"react16\"],div[data-qiankun=\"react16\"] {margin: 0}*:not(div[data-qiankun=\"react16\"]) {color: red}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 1, "text": "div, body, span", "declarations": "{color: red}"}, {"type": 1, "text": "body,html", "declarations": "{margin: 0}"}, {"type": 1, "text": "*:not(:root)", "declarations": "{color: red}"}]);
  });
  it("条件规则：@media/@supports 的条件原样保留、内部递归改写", () => {
    const rules = [{"type": 4, "text": "screen and (max-width: 300px)", "rules": [{"type": 1, "text": ".a", "declarations": "{color: red}"}, {"type": 5, "text": "@font-face{font-family:x}"}]}, {"type": 12, "text": "(display: grid)", "rules": [{"type": 1, "text": "body", "declarations": "{gap: 1px}"}]}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("@media screen and (max-width: 300px) {div[data-qiankun=\"react16\"] .a {color: red}@font-face{font-family:x}}@supports (display: grid) {div[data-qiankun=\"react16\"] {gap: 1px}}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 4, "text": "screen and (max-width: 300px)", "rules": [{"type": 1, "text": ".a", "declarations": "{color: red}"}, {"type": 5, "text": "@font-face{font-family:x}"}]}, {"type": 12, "text": "(display: grid)", "rules": [{"type": 1, "text": "body", "declarations": "{gap: 1px}"}]}]);
  });
  it("不参与作用域的其余两类：@import 与 @page 原样输出（字体名/动画名/分页仍全局打架）", () => {
    const rules = [{"type": 3, "text": "@import url(\"theme.css\");"}, {"type": 6, "text": "@page{margin:1cm}"}];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("@import url(\"theme.css\");@page{margin:1cm}");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([{"type": 3, "text": "@import url(\"theme.css\");"}, {"type": 6, "text": "@page{margin:1cm}"}]);
  });
  it("退化：空规则表 ⇒ 空串（幂等：同一份输入喂两次结果必须一字不差）", () => {
    const rules = [];
    const once = scopeCss(rules, "div[data-qiankun=\"react16\"]");
    expect(once).toEqual("");
    expect(scopeCss(JSON.parse(JSON.stringify(rules)), "div[data-qiankun=\"react16\"]")).toEqual(once);
    expect(rules).toEqual([]);
  });
  it("非法：未知规则类型（CSSRule.type 里没有 99）", () => {
    expect(() => scopeCss([{"type": 99, "text": "whatever"}] as never, "div[data-qiankun=\"react16\"]")).toThrow("unknown css rule type");
  });
});

